import{_ as o,l as i,o as e,c as l,v as r,p as d,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"UDP 校验与端口","description":"","frontmatter":{"title":"UDP 校验与端口","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/udp-checksum.md","filePath":"cs/udp-checksum.md","lastUpdated":1789023840000}'),h={name:"cs/udp-checksum.md"};function P(A,a,u,E,_,m){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="udp-校验与端口" tabindex="-1">UDP 校验与端口 <a class="header-anchor" href="#udp-校验与端口" aria-label="Permalink to &quot;UDP 校验与端口&quot;">​</a></h1><div class="epigraph"><p>端口把主机上的数据报交给某个套接字；校验和覆盖伪首部，发现的是端到端比特翻转，不是到达保证。</p><footer>—— 据 Postel, RFC 768；Kurose and Ross 对端口与校验的整理</footer></div><p><a href="/cs/udp">上一课</a>给出最薄传输：数据报、不保证序与到达。本课不重讲「无连接」。缺口是两个字段如何用：目的端口解复用到进程，校验和（IPv4 上可选、IPv6 上实质必有）把 <a href="/cs/ip-subnet">IP</a> 地址绑进检查范围。本课不把 TCP 握手提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/udp">UDP</a> 说有端口与可选校验，但没钉解复用键与伪首部。同一主机多个接收者：<a href="/cs/process-image">进程</a> 用端口区分。校验覆盖 UDP 头、载荷以及源/目的 IP 等伪首部字段，使「改了 IP 头却不动 UDP」也能被发现——链路 <a href="/cs/frame-crc">CRC</a> 覆盖不到中间节点改写。缺口是<strong>解复用与端到端检错</strong>，仍不是可靠流。</p><p><span class="marginnote">IPv4 校验和为 0 表示发送方未算。NAPT 改地址/端口后必须重算。分片重组前载荷可能不齐，校验在完整数据报上做。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送：填源端口（常由内核分配）、目的端口、长度，按 RFC 768 算校验。接收：按目的端口（及可选源过滤）投递；校验错则静默丢。无端口监听则 ICMP 端口不可达——那是上一层 ICMP 课已有的回报，UDP 自己不重试。</p>',8)),(e(),d(p,null,{default:t(()=>[c(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DG%5B%22UDP%20%E6%95%B0%E6%8D%AE%E6%8A%A5%22%5D%20--%3E%20PORT%5B%22%E6%8C%89%E7%9B%AE%E7%9A%84%E7%AB%AF%E5%8F%A3%E8%A7%A3%E5%A4%8D%E7%94%A8%22%5D%0A%20%20DG%20--%3E%20CKS%5B%22%E4%BC%AA%E9%A6%96%E9%83%A8%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20CKS%20--%3E%20DROP%5B%22%E9%94%99%E5%88%99%E4%B8%A2%22%5D%0A%20%20PORT%20--%3E%20SOCK%5B%22%E6%8A%95%E9%80%92%E5%88%B0%E5%A5%97%E6%8E%A5%E5%AD%97%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>端口是传输层名字，MAC 与 IP 都不是进程。<a href="/cs/layering-e2e">端到端</a> 在这一层第一次有了「进程到进程」的检错，但仍无序号。后课 TCP 用同一端口空间的另一协议号，把校验、序号、握手叠在一起。套接字 API 更后才把端口暴露给 <code>bind</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 QUIC 的 UDP 复用提前写完，不引入全部知名端口登记表。可靠、有序的字节流如何同步初始序号，下一课三次握手。</p><p>后课默认：数据报能按端口投递，校验错则丢。要流语义，下一课 TCP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>端口解复用到进程；校验含伪首部。</li><li>校验发现翻转，不恢复丢失。</li><li>有状态字节流从下一课握手开始。</li><li>出处：RFC 768；Kurose and Ross。</li></ul>',7))])}const D=o(h,[["render",P]]);export{C as __pageData,D as default};
